"use client";

import { useEffect, useMemo, useState } from "react";
import { AlertTriangle, Check, ExternalLink, Globe2, Loader2, RefreshCw, Search, XCircle } from "lucide-react";
import { addSiteEvent, addSitemap, applyPageVerification, extractCandidatesForEntry, mergeSitemapSync } from "@/lib/marca/site-reconciliation";
import { isAuthorizedSiteHost } from "@/lib/marca/site-security";
import { normalizeSiteUrl, validateSiteUrl } from "@/lib/marca/site-domain";
import { loadBrandSiteWorkspace, saveBrandSiteWorkspace } from "@/lib/marca/site-store";
import type { BrandSiteWorkspace, BrandSitemapSource, SiteCatalogEntry } from "@/lib/marca/site-contracts";

const field = "h-8 w-full rounded border border-slate-800 bg-black px-2 text-[11px] text-slate-200 outline-none focus:border-indigo-600";
const btn = "inline-flex h-7 items-center rounded border border-indigo-900 bg-indigo-950/20 px-2.5 text-[10px] font-bold text-indigo-300 hover:bg-indigo-950/50 disabled:cursor-not-allowed disabled:opacity-40";
const card = "rounded-lg border border-slate-900 bg-[#0b0c10] p-4";
const compact = "rounded border border-slate-900 bg-black/20 p-2";

type SiteList = { id: string; nome: string };
type ActionState = "idle" | "loading" | "saving" | "testing" | "syncing" | "verifying" | "extracting" | "importing";

function statusLabel(value: string) { return value.replaceAll("_", " "); }

export function SiteSitemapPanel({ brandId, siteUrl, saving, onSave }: { brandId: string; siteUrl: string; saving: boolean; onSave: (siteUrl: string) => Promise<void> }) {
  const [workspace, setWorkspace] = useState<BrandSiteWorkspace | null>(null);
  const [storageMode, setStorageMode] = useState("local_fallback");
  const [parseError, setParseError] = useState<string | null>(null);
  const [notice, setNotice] = useState<{ type: "success" | "error"; message: string } | null>(null);
  const [draft, setDraft] = useState(siteUrl || "");
  const [sitemapType, setSitemapType] = useState<BrandSitemapSource["type"]>("principal");
  const [sitemapAction, setSitemapAction] = useState<ActionState>("idle");
  const [catalogSelection, setCatalogSelection] = useState<Set<string>>(new Set());
  const [candidateSelection, setCandidateSelection] = useState<Set<string>>(new Set());
  const [lists, setLists] = useState<SiteList[]>([]);
  const [targetListId, setTargetListId] = useState("");
  const [importOpen, setImportOpen] = useState(false);

  useEffect(() => {
    const resetTimer = window.setTimeout(() => {
      setDraft(siteUrl || "");
      setWorkspace(null);
      setCatalogSelection(new Set());
      setCandidateSelection(new Set());
      setImportOpen(false);
    }, 0);
    let active = true;
    void loadBrandSiteWorkspace(brandId).then(result => { if (!active) return; setWorkspace(result.workspace); setParseError(result.parseError); }).catch(error => { if (active) setNotice({ type: "error", message: error instanceof Error ? error.message : "Não foi possível carregar o catálogo local." }); });
    void fetch(`/api/marca/site/lists?brandId=${encodeURIComponent(brandId)}`).then(async response => { const body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível carregar os silos."); return body; }).then(body => { if (active) { setLists(body.lists || []); setTargetListId(current => current || body.lists?.[0]?.id || ""); } }).catch(() => { if (active) setLists([]); });
    return () => { active = false; window.clearTimeout(resetTimer); };
  }, [brandId, siteUrl]);

  const persist = async (next: BrandSiteWorkspace, successMessage?: string) => {
    const mode = await saveBrandSiteWorkspace(next);
    setWorkspace(next);
    setStorageMode(mode === "indexeddb" ? "IndexedDB local" : "localStorage local");
    if (successMessage) setNotice({ type: "success", message: successMessage });
  };

  const run = async <T,>(action: () => Promise<T>) => { setNotice(null); try { return await action(); } catch (error) { setNotice({ type: "error", message: error instanceof Error ? error.message : "Operação não concluída." }); return null; } };

  const normalizedSite = validateSiteUrl(draft);
  const originalSite = validateSiteUrl(siteUrl || "");
  const siteDirty = normalizedSite.ok && normalizedSite.value !== (originalSite.ok ? originalSite.value : (siteUrl || "").trim());
  const primaryHost = useMemo(() => { try { return new URL(normalizeSiteUrl(siteUrl || "")).hostname; } catch { return ""; } }, [siteUrl]);
  const selectedCatalog = useMemo(() => workspace?.catalog.filter(item => catalogSelection.has(item.id)) || [], [catalogSelection, workspace]);
  const candidateRows = useMemo(() => workspace?.candidates.filter(item => selectedCatalog.some(entry => entry.id === item.catalogEntryId)) || [], [selectedCatalog, workspace]);
  const lastRun = workspace?.syncRuns.at(-1) || null;

  const addNewSitemap = () => void run(async () => {
    if (!workspace) return;
    const parsed = validateSiteUrl((document.getElementById("new-sitemap-url") as HTMLInputElement | null)?.value || "");
    if (!parsed.ok || !parsed.value) throw new Error(parsed.ok ? "Informe a URL do sitemap." : parsed.message);
    if (!primaryHost || !isAuthorizedSiteHost(new URL(parsed.value).hostname, primaryHost)) throw new Error("O sitemap deve pertencer ao domínio principal do site.");
    const result = addSitemap(workspace, { url: parsed.value, type: sitemapType });
    if (result.duplicate) { setNotice({ type: "error", message: "Este sitemap já está cadastrado para a marca." }); return; }
    await persist(result.workspace, "Sitemap cadastrado localmente.");
  });

  const testSitemap = (sitemap: BrandSitemapSource) => void run(async () => {
    if (!workspace) return;
    setSitemapAction("testing");
    try {
      const response = await fetch("/api/marca/site/sitemap/test", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId, sitemapUrl: sitemap.url }) });
      const body = await response.json(); if (!response.ok) throw new Error(body.error || "Teste de sitemap falhou.");
      const now = new Date().toISOString();
      const next = workspace.sitemaps.map(item => item.id === sitemap.id ? { ...item, status: "tested" as const, lastTestedAt: now, lastValidKind: body.result.kind, lastValidItemCount: body.result.itemCount, updatedAt: now } : item);
      await persist(addSiteEvent({ ...workspace, sitemaps: next, updatedAt: now }, "sitemap_tested", "local-user", sitemap.id, body.result, now), "Sitemap testado sem alterar o catálogo.");
    } finally { setSitemapAction("idle"); }
  });

  const syncSitemap = (sitemap: BrandSitemapSource) => void run(async () => {
    if (!workspace) return;
    setSitemapAction("syncing");
    try {
      const response = await fetch("/api/marca/site/sitemap/sync", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId, sitemapId: sitemap.id, sitemapUrl: sitemap.url }) });
      const body = await response.json(); if (!response.ok) throw new Error(body.error || "Sincronização falhou.");
      const started = addSiteEvent(workspace, "sitemap_sync_started", "local-user", sitemap.id, {}, new Date().toISOString());
      const next = mergeSitemapSync(started, sitemap.id, body, "local-user");
      await persist(next, body.run.status === "completed" ? "Sitemap sincronizado." : "Sincronização parcial; o estado anterior foi preservado.");
    } finally { setSitemapAction("idle"); }
  });

  const requestVerification = async (entry: SiteCatalogEntry) => {
    const response = await fetch("/api/marca/site/page/verify", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId, url: entry.normalizedUrl }) });
    const body = await response.json();
    if (!response.ok && !body.verificationStatus) throw new Error(body.error || "Verificação falhou.");
    if (!body.verification) throw new Error(body.error || "A página não retornou dados verificáveis.");
    return body.verification;
  };

  const verifySelected = () => void run(async () => {
    if (!workspace || !selectedCatalog.length) throw new Error("Selecione ao menos uma URL para verificar.");
    setSitemapAction("verifying");
    try {
      let next = workspace;
      for (const entry of selectedCatalog) {
        const verification = await requestVerification(entry);
        next = applyPageVerification(next, entry.id, verification);
      }
      await persist(next, `${selectedCatalog.length} página(s) verificada(s).`);
    } finally { setSitemapAction("idle"); }
  });

  const verifyOne = (entry: SiteCatalogEntry) => void run(async () => {
    if (!workspace) return;
    setSitemapAction("verifying");
    try {
      const verification = await requestVerification(entry);
      await persist(applyPageVerification(workspace, entry.id, verification), "Página verificada.");
    } finally { setSitemapAction("idle"); }
  });

  const extractSelected = () => void run(async () => {
    if (!workspace || !selectedCatalog.length) throw new Error("Selecione páginas verificadas para extrair candidatos.");
    setSitemapAction("extracting");
    try {
      const verified = selectedCatalog.filter(entry => entry.lastVerifiedAt);
      if (!verified.length) throw new Error("Verifique explicitamente as páginas antes de extrair candidatos.");
      const fresh = verified.flatMap(entry => extractCandidatesForEntry(entry));
      const previous = workspace.candidates.filter(candidate => !verified.some(entry => entry.id === candidate.catalogEntryId));
      const seen = new Set<string>();
      const candidates = [...previous, ...fresh.map(candidate => { const duplicate = seen.has(candidate.normalizedText); seen.add(candidate.normalizedText); return duplicate ? { ...candidate, status: "duplicate_batch" as const } : candidate; })];
      const now = new Date().toISOString();
      await persist(addSiteEvent({ ...workspace, candidates, updatedAt: now }, "keyword_candidates_created", "local-user", null, { count: fresh.length }, now), `${fresh.length} candidato(s) extraído(s) sem IA.`);
      setCandidateSelection(new Set(fresh.filter(candidate => candidate.status === "new").map(candidate => candidate.id)));
    } finally { setSitemapAction("idle"); }
  });

  const prepareImport = () => {
    if (!workspace) return;
    setImportOpen(true);
    setCandidateSelection(current => current.size ? current : new Set(candidateRows.filter(candidate => ["new", "exists_in_minerador"].includes(candidate.status)).map(candidate => candidate.id)));
    setNotice({ type: "success", message: "Prévia preparada. Nenhum item foi importado." });
  };

  const sendKeywords = () => void run(async () => {
    if (!workspace) return;
    const candidates = workspace.candidates.filter(candidate => candidateSelection.has(candidate.id));
    if (!candidates.length) throw new Error("Selecione keywords na prévia.");
    if (!targetListId) throw new Error("Selecione um silo/lista do Minerador.");
    setSitemapAction("importing");
    try {
      const batchId = crypto.randomUUID();
      const response = await fetch("/api/marca/site/import/keywords", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId, targetListId, batchId, candidates }) });
      const body = await response.json(); if (!response.ok) throw new Error(body.error || "Importação de keywords falhou.");
      const imported = new Set(body.imported || []); const existing = new Set(body.alreadyExists || []);
      const nextCandidates = workspace.candidates.map(candidate => imported.has(candidate.id) ? { ...candidate, status: "sent" as const } : existing.has(candidate.id) ? { ...candidate, status: "exists_in_minerador" as const } : candidate);
      const now = new Date().toISOString();
      const batch = { id: batchId, brandId, kind: "keywords" as const, status: "imported" as const, candidateIds: candidates.map(item => item.id), catalogEntryIds: [...new Set(candidates.map(item => item.catalogEntryId))], targetListId, snapshot: candidates, summary: { imported: (body.imported || []).length, alreadyExists: (body.alreadyExists || []).length, duplicateInBatch: (body.duplicateInBatch || []).length }, createdAt: now, completedAt: now, errorMessage: null };
      await persist(addSiteEvent({ ...workspace, candidates: nextCandidates, importBatches: [...workspace.importBatches, batch], updatedAt: now }, "keywords_sent_to_minerador", "local-user", batchId, { batchId, summary: batch.summary }, now), "Keywords enviadas ao Minerador como bruto, sem KGR ou aprovação.");
    } finally { setSitemapAction("idle"); }
  });

  const importLegacyContent = () => void run(async () => {
    if (!workspace || !selectedCatalog.length) throw new Error("Selecione artigos ou páginas verificadas.");
    const now = new Date().toISOString();
    const catalog = workspace.catalog.map(entry => selectedCatalog.some(item => item.id === entry.id) ? { ...entry, importStatus: "imported_as_legacy_content" as const } : entry);
    const batch = { id: crypto.randomUUID(), brandId, kind: "legacy_content" as const, status: "imported" as const, candidateIds: [], catalogEntryIds: selectedCatalog.map(item => item.id), targetListId: null, snapshot: selectedCatalog, summary: { imported: selectedCatalog.length }, createdAt: now, completedAt: now, errorMessage: null };
    await persist(addSiteEvent({ ...workspace, catalog, importBatches: [...workspace.importBatches, batch], updatedAt: now }, "legacy_contents_imported", "local-user", batch.id, { count: selectedCatalog.length }, now), "Conteúdos registrados como legados observados; nenhum DNA foi criado.");
  });

  const toggle = (set: Set<string>, id: string, setter: (next: Set<string>) => void) => { const next = new Set(set); if (next.has(id)) next.delete(id); else next.add(id); setter(next); };

  if (!workspace) return <section className={card}><Loader2 className="mr-2 inline h-4 w-4 animate-spin"/>Carregando catálogo local da marca…</section>;

  return <div className="space-y-3">
    <section className={`${card} max-w-6xl`}>
      <div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Globe2 className="h-4 w-4 text-indigo-400"/><h2 className="text-xs font-bold">Site principal</h2></div><p className="mt-1 text-[10px] text-slate-500">Sitemaps e verificações ficam limitados ao domínio principal e só são executados por ação explícita.</p></div><span className="rounded border border-amber-900/50 bg-amber-950/20 px-2 py-1 text-[9px] text-amber-300">Persistência: {storageMode}</span></div>
      <div className="mt-3 flex flex-wrap items-center gap-2"><input className={`${field} max-w-xl`} value={draft} onChange={event => setDraft(event.target.value)} placeholder="https://exemplo.com.br"/><button className={btn} disabled={saving || !normalizedSite.ok || !siteDirty} onClick={() => void run(() => onSave(normalizedSite.ok ? normalizedSite.value : ""))}><Check className="mr-1 h-3 w-3"/>{saving ? "Salvando…" : "Salvar site"}</button>{normalizedSite.ok && normalizedSite.value && <a className="text-[10px] text-indigo-400" href={normalizedSite.value} target="_blank" rel="noreferrer"><ExternalLink className="mr-1 inline h-3 w-3"/>Abrir</a>}</div>
    </section>
    {parseError && <p role="alert" className="max-w-6xl rounded border border-amber-900/50 bg-amber-950/20 p-2 text-[10px] text-amber-300"><AlertTriangle className="mr-1 inline h-3 w-3"/>Estado local inválido preservado; corrija ou exporte o recovery antes de substituir: {parseError}</p>}
    {notice && <p role={notice.type === "error" ? "alert" : "status"} className={`${notice.type === "error" ? "border-red-900/50 bg-red-950/20 text-red-300" : "border-emerald-900/50 bg-emerald-950/20 text-emerald-300"} max-w-6xl rounded border p-2 text-[10px]`}>{notice.message}</p>}
    <section className={`${card} max-w-6xl`}>
      <div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="text-xs font-bold">Sitemaps</h2><p className="mt-1 text-[10px] text-slate-500">Teste valida XML sem alterar o catálogo. Sincronizar é explícito, deduplicado e marca ausências como obsoletas.</p></div><span className="text-[9px] text-slate-600">{workspace.sitemaps.length} cadastrado(s)</span></div>
      <div className="mt-3 grid gap-2 md:grid-cols-[minmax(0,1fr)_150px_auto]"><input id="new-sitemap-url" className={field} placeholder="https://exemplo.com.br/sitemap.xml"/><select className={field} value={sitemapType} onChange={event => setSitemapType(event.target.value as BrandSitemapSource["type"])}>{[["principal", "Sitemap principal"], ["sitemap_index", "Sitemap index"], ["posts", "Posts"], ["paginas", "Páginas"], ["produtos", "Produtos"], ["categorias", "Categorias"], ["outro", "Outro"]].map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><button className={btn} onClick={addNewSitemap}><Check className="mr-1 h-3 w-3"/>Adicionar sitemap</button></div>
      <div className="mt-3 space-y-2">{workspace.sitemaps.length ? workspace.sitemaps.map(sitemap => <div key={sitemap.id} className={`${compact} flex flex-wrap items-center justify-between gap-2`}><div className="min-w-0"><a href={sitemap.url} target="_blank" rel="noreferrer" className="block truncate text-[10px] text-indigo-300">{sitemap.url}</a><span className="text-[9px] text-slate-600">{statusLabel(sitemap.status)} · {sitemap.urlCount} URL(s) · {sitemap.errorCount} erro(s) · {sitemap.lastSyncedAt ? new Date(sitemap.lastSyncedAt).toLocaleString("pt-BR") : "nunca sincronizado"}</span></div><div className="flex flex-wrap gap-1"><button className={btn} disabled={sitemapAction !== "idle"} onClick={() => testSitemap(sitemap)}>Testar</button><button className={btn} disabled={sitemapAction !== "idle"} onClick={() => syncSitemap(sitemap)}><RefreshCw className="mr-1 h-3 w-3"/>Sincronizar</button><button className={btn} onClick={() => setCatalogSelection(new Set(workspace.catalog.filter(entry => entry.sourceSitemapIds.includes(sitemap.id)).map(entry => entry.id)))}>Ver URLs</button></div></div>) : <p className="text-[10px] text-slate-600">Nenhum sitemap cadastrado.</p>}</div>
    </section>
    <section className="grid max-w-6xl gap-3 md:grid-cols-5"><div className={card}><strong className="text-lg">{workspace.catalog.length}</strong><p className="text-[9px] text-slate-500">URLs no catálogo</p></div><div className={card}><strong className="text-lg">{workspace.catalog.filter(item => item.lastVerifiedAt).length}</strong><p className="text-[9px] text-slate-500">verificadas</p></div><div className={card}><strong className="text-lg">{workspace.catalog.filter(item => item.verificationStatus === "canonical_confirmed").length}</strong><p className="text-[9px] text-slate-500">canonicals confirmados</p></div><div className={card}><strong className="text-lg">{workspace.candidates.length}</strong><p className="text-[9px] text-slate-500">keywords candidatas</p></div><div className={card}><strong className="text-lg">{workspace.importBatches.filter(batch => batch.status === "imported").length}</strong><p className="text-[9px] text-slate-500">lotes concluídos</p></div></section>
    {lastRun && <section className={`${card} max-w-6xl`}><h2 className="text-xs font-bold">Resumo da sincronização</h2><div className="mt-2 grid gap-2 text-[10px] md:grid-cols-6"><span>Estado: <strong>{statusLabel(lastRun.status)}</strong></span><span>Encontradas: <strong>{lastRun.foundCount}</strong></span><span>Novas: <strong>{lastRun.newCount}</strong></span><span>Atualizadas: <strong>{lastRun.updatedCount}</strong></span><span>Ausentes: <strong>{lastRun.missingCount}</strong></span><span>Erros: <strong>{lastRun.errorCount}</strong></span></div></section>}
    <section className={`${card} max-w-6xl`}><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="text-xs font-bold">Catálogo de conteúdos</h2><p className="mt-1 text-[10px] text-slate-500">Seleção controla ações; a tabela não dispara requisições externas.</p></div><div className="flex flex-wrap gap-1"><button className={btn} disabled={!catalogSelection.size || sitemapAction !== "idle"} onClick={verifySelected}><Search className="mr-1 h-3 w-3"/>Verificar selecionadas</button><button className={btn} disabled={!catalogSelection.size || sitemapAction !== "idle"} onClick={extractSelected}>Extrair dados</button><button className={btn} disabled={!catalogSelection.size} onClick={prepareImport}>Preparar importação</button></div></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[980px] text-[10px]"><thead className="text-left text-slate-600"><tr><th className="p-2">Sel.</th><th className="p-2">Título / H1</th><th className="p-2">Tipo</th><th className="p-2">URL</th><th className="p-2">Canonical</th><th className="p-2">Indexabilidade</th><th className="p-2">Status</th><th className="p-2">Ação</th></tr></thead><tbody>{workspace.catalog.map(entry => <tr key={entry.id} className="border-t border-slate-900"><td className="p-2"><input type="checkbox" checked={catalogSelection.has(entry.id)} onChange={() => toggle(catalogSelection, entry.id, setCatalogSelection)}/></td><td className="max-w-[190px] p-2"><strong className="block truncate">{entry.title || "Título não verificado"}</strong><span className="text-slate-600">{entry.h1 || "H1 pendente"}</span></td><td className="p-2">{entry.pageType}</td><td className="max-w-[230px] p-2"><a className="block truncate text-indigo-300" href={entry.normalizedUrl} target="_blank" rel="noreferrer">{entry.normalizedUrl}</a></td><td className="max-w-[180px] p-2 truncate">{entry.declaredCanonicalUrl || "ausente"}</td><td className="p-2">{entry.indexability}</td><td className="p-2">{statusLabel(entry.verificationStatus)} · {statusLabel(entry.importStatus)}</td><td className="p-2"><button className={btn} disabled={sitemapAction !== "idle"} onClick={() => verifyOne(entry)}>Verificar</button></td></tr>)}</tbody></table>{!workspace.catalog.length && <p className="p-4 text-center text-[10px] text-slate-600">Sincronize um sitemap para criar o catálogo.</p>}</div></section>
    {importOpen && <section className={`${card} max-w-6xl border-indigo-900/50`}><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="text-xs font-bold">Prévia de importação</h2><p className="mt-1 text-[10px] text-slate-500">Nada será escrito até uma ação explícita.</p></div><button className={btn} onClick={() => setImportOpen(false)}><XCircle className="mr-1 h-3 w-3"/>Fechar</button></div><div className="mt-3 grid gap-3 lg:grid-cols-2"><div><h3 className="text-[10px] font-bold">Keywords para o Minerador ({candidateRows.length})</h3><div className="mt-2 max-h-64 space-y-1 overflow-auto">{candidateRows.map(candidate => <label key={candidate.id} className="flex items-start gap-2 border-b border-slate-900 py-1.5"><input type="checkbox" checked={candidateSelection.has(candidate.id)} onChange={() => toggle(candidateSelection, candidate.id, setCandidateSelection)}/><span><strong>{candidate.text}</strong><span className="block text-[9px] text-slate-600">{candidate.sourceField} · {candidate.status} · {candidate.sourceUrl}</span></span></label>)}{!candidateRows.length && <p className="text-[10px] text-slate-600">Extraia dados de páginas verificadas para gerar candidatos.</p>}</div><div className="mt-3 flex gap-2"><select className={field} value={targetListId} onChange={event => setTargetListId(event.target.value)}><option value="">Selecione o silo/lista de destino</option>{lists.map(list => <option key={list.id} value={list.id}>{list.nome}</option>)}</select><button className={btn} disabled={!candidateSelection.size || !targetListId || sitemapAction !== "idle"} onClick={sendKeywords}>Enviar ao Minerador</button></div><p className="mt-2 text-[9px] text-amber-300">Entram como bruto, sem volume, KGR, intenção ou aprovação inventados.</p></div><div><h3 className="text-[10px] font-bold">Conteúdos publicados legados ({selectedCatalog.length})</h3><div className="mt-2 space-y-1">{selectedCatalog.map(entry => <div key={entry.id} className="rounded border border-slate-900 p-2 text-[10px]"><strong>{entry.title || entry.normalizedUrl}</strong><p className="text-slate-500">{entry.pageType} · {entry.declaredCanonicalUrl || "canonical ausente"} · {entry.importStatus}</p></div>)}{!selectedCatalog.length && <p className="text-[10px] text-slate-600">Selecione páginas no catálogo.</p>}</div><button className={`${btn} mt-3`} disabled={!selectedCatalog.length} onClick={importLegacyContent}>Registrar conteúdos legados selecionados</button><p className="mt-2 text-[9px] text-slate-500">Não cria ArticleDNA, SiloDNA, ContentPlan, autor ou aprovação.</p></div></div></section>}
    <section className={`${card} max-w-6xl`}><h2 className="text-xs font-bold">Histórico da aba</h2><div className="mt-2 space-y-1">{workspace.events.slice(-12).reverse().map(event => <div key={event.id} className="flex flex-wrap justify-between gap-2 border-b border-slate-900 py-1 text-[9px]"><span>{statusLabel(event.eventType)}</span><span className="text-slate-600">{new Date(event.occurredAt).toLocaleString("pt-BR")}</span></div>)}{!workspace.events.length && <p className="text-[10px] text-slate-600">Nenhum evento local ainda.</p>}</div></section>
  </div>;
}
